const message = $json.message ?? $json.body?.message ?? {
  chat: { id: $json.body?.chatId },
  message_id: $json.body?.messageId ?? 0,
  text: $json.body?.text,
};

if (!message?.chat?.id) {
  throw new Error('Telegram chat ID is missing');
}

const chatId = String(message.chat.id);
const messageId = Number(message.message_id);
const text = String(message.text ?? message.caption ?? '')
  .replace(/[\u200B-\u200D\uFEFF]/g, '')
  .trim();

const help = () => ({
  intent: 'help',
  chatId,
  messageId,
  helpHtml: '<b>Spotipy</b>\n\n/song &lt;track or Spotify link&gt;\n/album &lt;Spotify album link&gt;\n/playlist &lt;Spotify playlist link&gt;\n/search &lt;artist or track&gt;\n\nSend a Spotify link directly to download it.',
});

if (!text || /^\/(?:start|help)(?:@\w+)?$/i.test(text)) {
  return help();
}

const command = text.match(/^\/(song|spotify|album|playlist|search)(?:@\w+)?(?:\s+([\s\S]+))?$/i);
const spotifyUrl = text.match(/https?:\/\/open\.spotify\.com\/(?:intl-[^/]+\/)?(?:track|album|playlist)\/[A-Za-z0-9]+(?:\?[^\s]*)?/i)?.[0] ?? null;

const action = command?.[1]?.toLowerCase() ?? (spotifyUrl ? 'song' : 'search');
const query = String(command?.[2] ?? text).trim();

if (!query || (action !== 'search' && !spotifyUrl && query.length > 1000)) {
  return help();
}

if (action === 'search') {
  return { intent: 'search', chatId, messageId, query: query.slice(0, 500) };
}

const resourceKind = spotifyUrl?.match(/open\.spotify\.com\/(?:intl-[^/]+\/)?(track|album|playlist)\//i)?.[1]?.toLowerCase() ?? null;
if (action === 'album' && resourceKind && resourceKind !== 'album') {
  return { ...help(), helpHtml: 'Please send a Spotify <b>album</b> link after /album.' };
}
if (action === 'playlist' && resourceKind && resourceKind !== 'playlist') {
  return { ...help(), helpHtml: 'Please send a Spotify <b>playlist</b> link after /playlist.' };
}

const executionId = String($execution.id ?? Date.now());
const timestamp = Date.now();
const requestId = `telegram-${executionId}-${timestamp}`;
const payload = {
  jobId: `${executionId}-${timestamp}`,
  chatId,
  requestId,
  repiSessionId: `telegram-${chatId}-${messageId}`, 
  operation: 'download',
  queries: [query.slice(0, 1000)],
  sourceUrl: null,
  spotifyUrl,
  format: 'mp3',
  delivery: 'individual',
  collectionId: null,
  options: {
    audioProviders: [],
    lyricsProviders: ['musixmatch', 'genius', 'synced', 'azlyrics'],
    overwrite: 'skip',
    restrict: 'strict',
    albumType: null,
    threads: 4,
    maxRetries: 3,
    maxFilenameLength: 180,
    preload: false,
    printErrors: true,
    sponsorBlock: false,
    playlistNumbering: false,
    playlistRetainTrackCover: false,
    scanForSongs: false,
    fetchAlbums: false,
    addUnavailable: false,
    generateLrc: false,
    forceUpdateMetadata: false,
    syncWithoutDeleting: false,
    redownload: false,
    skipAlbumArt: false,
    skipExplicit: false,
    onlyVerifiedResults: false,
    dontFilterResults: false,
    ytmData: false,
    createSkipFile: false,
    respectSkipFile: false,
    syncRemoveLrc: false,
  },
};

const intent = resourceKind === 'track'
  ? 'resolveDirectTrack'
  : (action === 'song' || action === 'spotify') && !spotifyUrl
    ? 'resolveDownload'
    : 'download';

const directTrackId = resourceKind === 'track'
  ? String(spotifyUrl ?? '').split('/track/')[1]?.split(/[?#&]/)[0] ?? null
  : null;

return {
  intent,
  chatId,
  messageId,
  query,
  directTrackId,
  payloadB64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
};

const context = $('Normalize music request').first().json;
const candidates = $input.all().flatMap((item) =>
  Array.isArray(item.json?.tracks?.items) ? item.json.tracks.items : [item.json],
);

const escapeHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;');

const lines = candidates.slice(0, 5).map((track, index) => {
  const title = String(track.name ?? '').trim();
  const artists = Array.isArray(track.artists)
    ? track.artists.map((artist) => artist?.name ?? artist).filter(Boolean).join(', ')
    : String(track.artist ?? '').trim();
  const album = String(track.album?.name ?? track.albumName ?? '').trim();
  const url = String(track.external_urls?.spotify ?? track.spotifyUrl ?? '').trim();

  if (!title || !url) return null;

  return `${index + 1}. <b>${escapeHtml(title)}</b>${artists ? ` — ${escapeHtml(artists)}` : ''}${album ? `\n<i>${escapeHtml(album)}</i>` : ''}\n${escapeHtml(url)}`;
}).filter(Boolean);

return [{
  json: {
    chatId: context.chatId,
    messageId: context.messageId,
    html: lines.length
      ? `<b>Verified Spotify results</b>\n\n${lines.join('\n\n')}\n\nSend /song followed by one of those Spotify links to download it.`
      : 'No verified Spotify track was found. Try a more specific title and artist.',
  },
}];

