const raw = String($json.stdout ?? '').trim();
let result;

try {
  result = JSON.parse(raw);
} catch {
  result = {
    status: 'failed',
    error: String($json.stderr ?? '').trim() || raw || 'The download runner returned an invalid response',
    files: [],
    tracks: [],
  };
}

const completed = ['completed', 'partial'].includes(String(result.status ?? '').toLowerCase())
  && Array.isArray(result.files)
  && result.files.length > 0;
const error = String(result.error ?? result.message ?? 'No audio files were produced').slice(0, 1000);
const escapeHtml = (value) => String(value)
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;');

return {
  chatId: context.chatId,
  messageId: context.messageId,
  completed,
  result: {
    ...result,
    files: Array.isArray(result.files) ? result.files : [],
    tracks: Array.isArray(result.tracks) ? result.tracks : [],
  },
  failureHtml: `<b>Download failed</b>\n${escapeHtml(error)}`,
