const result = envelope.result ?? { files: [], tracks: [] };
const CAPTION_LIMIT = 1024;

function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

function escapeAttribute(value) {
  return escapeHtml(value)
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&apos;');
}

function stripLrcTimestamps(value) {
  return String(value ?? '')
    .replace(/\r/g, '')
    .replace(/\[(?:\d{1,2}:)?\d{1,2}:\d{2}(?:[.:]\d{1,3})?\]\s*/g, '')
    .split('\n')
    .map((line) => line.trimEnd())
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function truncateAtBoundary(value, limit) {
  const text = String(value ?? '');

  if (text.length <= limit) {
    return { text, truncated: false };
  }

  const candidate = text.slice(0, Math.max(0, limit)).trimEnd();
  const boundary = Math.max(candidate.lastIndexOf('\n'), candidate.lastIndexOf(' '));
  const safeText = boundary > Math.floor(limit * 0.65)
    ? candidate.slice(0, boundary).trimEnd()
    : candidate;

  return { text: safeText, truncated: true };
}

function buildFacts(track) {
  const facts = [];
  const year = String(track.year ?? track.date ?? '').match(/\b\d{4}\b/)?.[0] ?? '';
  const trackNumber = Number(track.trackNumber);
  const trackCount = Number(track.trackCount);
  const publisher = String(track.publisher ?? '').trim();

  if (year) facts.push(year);
  if (Number.isInteger(trackNumber) && trackNumber > 0) {
    facts.push(
      Number.isInteger(trackCount) && trackCount > 0
        ? `${trackNumber}/${trackCount}`
        : String(trackNumber),
    );
  }
  if (publisher) facts.push(publisher);

  return facts.slice(0, 3);
}

function buildCaption({ title, artist, album, facts, lyrics, spotifyUrl }) {
  const titleText = truncateAtBoundary(title, 120).text;
  const artistBudget = Math.max(0, 160 - titleText.length - 3);
  const artistText = truncateAtBoundary(artist, artistBudget).text;
  const heading = [titleText, artistText].filter(Boolean).join(' — ');
  const albumLine = truncateAtBoundary(album, 120).text;
  const factsText = Array.isArray(facts) ? facts.filter(Boolean).join(' · ') : '';
  const factsLine = factsText ? `[${factsText}]` : '';
  const footer = spotifyUrl ? 'Spotify' : '';
  const lyricsText = stripLrcTimestamps(lyrics);
  const headerText = [heading, albumLine, factsLine].filter(Boolean).join('\n');
  const lyricSeparator = headerText && lyricsText ? 1 : 0;
  const footerSeparator = footer && (headerText || lyricsText) ? 1 : 0;
  const fixedLength = headerText.length + footer.length + lyricSeparator + footerSeparator;
  const truncationMarker = '\n…';
  const lyricLimit = Math.max(0, CAPTION_LIMIT - fixedLength);
  const needsTruncation = lyricsText.length > lyricLimit;
  const lyric = truncateAtBoundary(
    lyricsText,
    Math.max(0, lyricLimit - (needsTruncation ? truncationMarker.length : 0)),
  );
  const quote = lyric.text
    ? `<blockquote expandable>${escapeHtml(lyric.text)}${lyric.truncated ? truncationMarker : ''}</blockquote>`
    : '';
  const headingHtml = [
    titleText ? `<code>${escapeHtml(titleText)}</code>` : '',
    artistText ? `<b>${escapeHtml(artistText)}</b>` : '',
  ].filter(Boolean).join(' — ');

  return [
    headingHtml,
    albumLine ? `<b><i>${escapeHtml(albumLine)}</i></b>` : '',
    factsLine ? `<i>${escapeHtml(factsLine)}</i>` : '',
    quote,
    footer ? `<a href="${escapeAttribute(spotifyUrl)}">${footer}</a>` : '',
  ].filter(Boolean).join('\n');
}

const deliveries = (Array.isArray(result.files) ? result.files : []).map((remotePath, index) => {
  const track = result.tracks.find((candidate) => candidate?.remotePath === remotePath) ?? result.tracks[index] ?? {};
  const fileName = String(track.fileName ?? remotePath.split('/').pop() ?? `audio-${index + 1}.mp3`);
  const title = String(track.title ?? fileName.replace(/\.[^.]+$/, ''));
  const artist = String(track.artist ?? (Array.isArray(track.artists) ? track.artists.join(', ') : ''));
  const album = String(track.album ?? '');
  const duration = Number(track.duration) || 0;
  const spotifyUrl = String(track.spotifyUrl ?? '');
  const facts = buildFacts(track);

  return {
    chatId: envelope.chatId,
    remotePath,
    fileName,
    title,
    artist,
    duration,
    caption: buildCaption({
      title,
      artist,
      album,
      facts,
      lyrics: track.lyrics,
      spotifyUrl,
    }),
  };
});

return deliveries.map((delivery) => ({
  json: {
    jobDirectory: String(result.jobDirectory ?? ''),
    ...delivery,
  },
}));

