      facts,
      lyrics: track.lyrics,
      spotifyUrl,
    }),
  };
});

return deliveries.map((delivery) => ({
  json: {
    jobDirectory: String(result.jobDirectory ?? ''),
    ...delivery,
  },
}));

const context = $('Normalize music request').first().json;
const candidates = $input.all().flatMap((item) =>
  Array.isArray(item.json?.tracks?.items) ? item.json.tracks.items : [item.json],
);
const track = candidates.find((candidate) =>
  String(candidate?.external_urls?.spotify ?? candidate?.spotifyUrl ?? '').trim(),
);
const spotifyUrl = String(track?.external_urls?.spotify ?? track?.spotifyUrl ?? '').trim();

if (!spotifyUrl) {
  return [{
    json: {
      chatId: context.chatId,
      messageId: context.messageId,
      resolved: false,
      failureHtml: '<b>Download failed</b>\nNo matching Spotify track was found. Try a more specific title and artist.',
    },
  }];
}

const title = String(track?.name ?? '').trim();
const artists = Array.isArray(track?.artists)
  ? track.artists.map((artist) => String(artist?.name ?? artist ?? '').trim()).filter(Boolean)
  : [];
const metadataQuery = [artists.join(', '), title].filter(Boolean).join(' - ').slice(0, 1000);

if (!metadataQuery) {
  return [{
    json: {
      chatId: context.chatId,
      messageId: context.messageId,
      resolved: false,
      failureHtml: '<b>Download failed</b>\nSpotify returned incomplete track metadata. Try a more specific title and artist.',
    },
  }];
}

const payload = JSON.parse(Buffer.from(String(context.payloadB64), 'base64').toString('utf8'));
payload.spotifyUrl = spotifyUrl;
payload.metadataQuery = metadataQuery;
payload.queries = [metadataQuery];

return [{
  json: {
    chatId: context.chatId,
    messageId: context.messageId,
    resolved: true,
    payloadB64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
  },
}];

const request = $('Normalize music request').first().json;
const result = $json.result ?? {};

return {
  ...request,
  statusMessageId: Number(result.message_id ?? 0),
};
